import "../../styles/index-base.css";
import "../../styles/components/switch.css";
import { Switch as SwitchPrimitive } from "@base-ui/react/switch";
import { useId } from "react";
import { cn } from "../../lib/cn";

type SwitchProps = SwitchPrimitive.Root.Props & {
  label?: string;
  description?: string;
};

export function Switch({ className, label, description, id: providedId, ...props }: SwitchProps) {
  const generatedId = useId();
  const id = providedId ?? generatedId;
  return (
    <div className="ix-choice-row ix-choice-row--spread">
      {label && (
        <label htmlFor={id} className="ix-choice-copy">
          <span>{label}</span>
          {description && <small>{description}</small>}
        </label>
      )}
      <SwitchPrimitive.Root id={id} className={cn("ix-switch", className)} {...props}>
        <SwitchPrimitive.Thumb className="ix-switch__thumb" />
      </SwitchPrimitive.Root>
    </div>
  );
}

/* Generated from src/styles.css. Do not edit directly. */

@layer index.tokens, index.base, index.components;

@layer index.components {
.ix-choice-row { display: flex; align-items: flex-start; gap: 9px; }

.ix-choice-row--spread { align-items: center; justify-content: space-between; }

.ix-choice-copy { display: grid; gap: 3px; color: var(--ix-ink); font-size: 13.5px; cursor: pointer; }

.ix-choice-copy small { color: var(--ix-ink-tertiary); font-size: 11.5px; font-weight: 400; line-height: 1.45; }

.ix-choice-row:has([data-disabled]) .ix-choice-copy { opacity: 0.48; cursor: not-allowed; }

.ix-switch { position: relative; display: inline-flex; width: 32px; height: 18px; flex: none; align-items: center; padding: 1px; border: 1px solid var(--ix-control-border); border-radius: 999px; background: var(--ix-switch-track); cursor: pointer; transition: background var(--ix-fast), border-color var(--ix-fast); }

.ix-switch::after { position: absolute; inset: -10px; content: ""; }

.ix-switch[data-checked] { border-color: var(--ix-inverse); background: var(--ix-inverse); }

.ix-switch[data-disabled] { opacity: 0.42; cursor: not-allowed; }

.ix-switch__thumb { display: block; width: 14px; height: 14px; border-radius: 50%; background: var(--ix-switch-thumb); box-shadow: 0 1px 3px rgb(0 0 0 / 0.24); transform: translateX(0); transition: transform 180ms var(--ix-ease-out); }

.ix-switch[data-checked] .ix-switch__thumb { background: var(--ix-on-inverse); transform: translateX(14px); }

@media (forced-colors: active) {
.ix-switch { forced-color-adjust: none; border-color: CanvasText; background: Canvas; color: CanvasText; }

.ix-switch[data-checked] { background: Highlight; color: HighlightText; }
}

:root[data-theme="dark"] .ix-switch[data-checked] { box-shadow: none; }

:root[data-theme="dark"] .ix-switch[data-checked] .ix-switch__thumb { background: var(--ix-on-inverse); }

@media (prefers-reduced-motion: reduce) {
.ix-switch__thumb { transition-duration: 0.01ms; }
}
}
